window.TURATH_DATA.hadith.push(...[{"num":16508,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «إِذَا كَانَ يَوْمُ الْقِيَامَةِ دَفَعَ اللَّهُ عَزَّ وَجَلَّ إِلَى كُلِّ مُسْلِمٍ يَهُودِيًّا أَوْ نَصْرَانِيًّا فَيَقُولُ هَذَا فَكَاكُكَ مِنَ النَّارِ»"],"takhrij":"صحيح: رواه مسلم (٢٧٦٧).","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2767).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":66,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Messenger of Allah ﷺ said: “On the Day of Resurrection, Allah, Mighty and Majestic, will assign to every Muslim a Jew or a Christian and will say: ‘This is your ransom from the Fire.’”"]},"buhuth":{"ar":["قوله: “فكاكك من النار” أي أنت كنت معرضًا لدخول النار، ولكن من أجل اختيارك الإسلام جعل اللّٰه فكاكك في النار يهوديًا أو نصرانيًا (ويلحق بهم عموم الكفار)، فكان ذلك فكاكه من النار."],"en":["Regarding the phrase “your ransom from the Fire,” the author explains:","You were exposed to the possibility of entering the Fire, but because you chose Islam, Allah placed in the Fire in your stead a Jew or a Christian—and the generality of disbelievers is included with them—so that became his ransom from the Fire."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2767}],"voc":["muslim",7011]},{"num":16509,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري، عن النبي ﷺ قال:","((لا يموت رجل مسلم إلا أدخل اللّٰه مكانه النار يهوديًا أو نصرانيًا))."],"takhrij":"صحيح: رواه مسلم (٥٠ :٢٧٦٧).","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (50 :2767).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":66,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Prophet ﷺ said: “No Muslim man dies except that Allah admits into the Fire in his place a Jew or a Christian.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":50}]},{"num":16510,"demo":false,"sanad":"","matn":["عَنْ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «يَجِيءُ يَوْمَ الْقِيَامَةِ نَاسٌ مِنَ الْمُسْلِمِينَ بِذُنُوبٍ أَمْثَالِ الْجِبَالِ فَيَغْفِرُهَا اللَّهُ لَهُمْ وَيَضَعُهَا عَلَى الْيَهُودِ وَالنَّصَارَى»"],"takhrij":"صحيح: رواه مسلم (٥١ :٢٧٦٧).","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (51 :2767).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":66,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā narrated that the Prophet ﷺ said: “On the Day of Resurrection, some Muslims will come with sins like mountains. Allah will forgive them and place them upon the Jews and Christians.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":51}],"voc":["muslim",7014]},{"num":16511,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «مَا مِنْكُمْ مِنْ أَحَدٍ إِلاَّ لَهُ مَنْزِلاَنِ مَنْزِلٌ فِي الْجَنَّةِ وَمَنْزِلٌ فِي النَّارِ فَإِذَا مَاتَ فَدَخَلَ النَّارَ وَرِثَ أَهْلُ الْجَنَّةِ مَنْزِلَهُ فَذَلِكَ قَوْلُهُ تَعَالَى {أُولَئِكَ هُمُ الْوَارِثُونَ }»"],"takhrij":"صحيح: رواه ابن ماجه (٤٣٤١)، والبيهقي في الشعب (٣٧٣)، وابن أبي حاتم كما ذكر ابن كثير في تفسيره (٤٦٤/٥).","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (4341), al-Bayhaqī in al-Shuʿab (373), and Ibn Abī Ḥātim, as cited by Ibn Kathīr in his Tafsīr (5/464).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":66,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “There is none among you except that he has two dwellings: a dwelling in Paradise and a dwelling in the Fire. If he dies and enters the Fire, the people of Paradise will inherit his dwelling. That is the meaning of the statement of Allah, the Exalted: ‘Those are the inheritors.’ [al-Muʾminūn 23:10]”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":4341},{"key":"البیہقی/الشعب","label":"البيهقي في الشعب","number":373},{"key":"ابن_ابی_حاتم_کما_ذکر_ابن_کثیر/تفسیرہ","label":"ابن أبي حاتم كما ذكر ابن كثير في تفسيره","number":464}],"voc":["ibnmajah",4341]},{"num":16512,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ مِنَ الْعُقُوبَةِ مَا طَمِعَ بِجَنَّتِهِ أَحَدٌ وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنَ الرَّحْمَةِ مَا قَنِطَ مِنْ جَنَّتِهِ أَحَدٌ»"],"takhrij":"صحيح: رواه مسلم (٢٧٥٥).","grade":"صحيح","chapter_ar":"باب ما جاء في شدة عقوبة الله وسعة رحمته","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2755).","chapter_en":"What Has Been Narrated Concerning the Severity of Allah’s Punishment and the Vastness of His Mercy","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If the believer knew the full extent of the punishment with Allah, no one would hope for His Paradise. And if the disbeliever knew the full extent of the mercy with Allah, no one would despair of His Paradise.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2755}],"voc":["muslim",6979]},{"num":16513,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ»"],"takhrij":"صحيح: رواه مسلم (٢٨٢٢).","grade":"صحيح","chapter_ar":"باب حفت الجنة بالمكاره وحفت النار بالشهوات","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2822).","chapter_en":"Paradise Is Surrounded by Hardships and the Fire Is Surrounded by Desires","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Paradise is surrounded by hardships, and the Fire is surrounded by desires.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2822}],"voc":["muslim",7130]},{"num":16514,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «حُجِبَتِ النَّارُ بِالشَّهَوَاتِ، وَحُجِبَتِ الْجَنَّةُ بِالْمَكَارِهِ»"],"takhrij":"متفق عليه: رواه البخاري (٦٤٨٧)، ومسلم (٢٨٢٣).","grade":"متفق عليه","chapter_ar":"باب حفت الجنة بالمكاره وحفت النار بالشهوات","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6487) and Muslim (2823).","chapter_en":"Paradise Is Surrounded by Hardships and the Fire Is Surrounded by Desires","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The Fire has been veiled by desires, and Paradise has been veiled by hardships.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6487},{"key":"muslim","label":"مسلم","number":2823}],"voc":["bukhari",6487]},{"num":16515,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «لَمَّا خَلَقَ اللَّهُ الْجَنَّةَ وَالنَّارَ أَرْسَلَ جِبْرِيلَ إِلَى الْجَنَّةِ فَقَالَ انْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لأَهْلِهَا فِيهَا قَالَ فَجَاءَهَا وَنَظَرَ إِلَيْهَا وَإِلَى مَا أَعَدَّ اللَّهُ لأَهْلِهَا فِيهَا قَالَ فَرَجَعَ إِلَيْهِ قَالَ فَوَعِزَّتِكَ لاَ يَسْمَعُ بِهَا أَحَدٌ إِلاَّ دَخَلَهَا. فَأَمَرَ بِهَا فَحُفَّتْ بِالْمَكَارِهِ فَقَالَ ارْجِعْ إِلَيْهَا فَانْظُرْ إِلَى مَا أَعْدَدْتُ لأَهْلِهَا فِيهَا قَالَ فَرَجَعَ إِلَيْهَا فَإِذَا هِيَ قَدْ حُفَّتْ بِالْمَكَارِهِ فَرَجَعَ إِلَيْهِ فَقَالَ وَعِزَّتِكَ لَقَدْ خِفْتُ أَنْ لاَ يَدْخُلَهَا أَحَدٌ. قَالَ اذْهَبْ إِلَى النَّارِ فَانْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لأَهْلِهَا فِيهَا. فَإِذَا هِيَ يَرْكَبُ بَعْضُهَا بَعْضًا فَرَجَعَ إِلَيْهِ فَقَالَ وَعِزَّتِكَ لاَ يَسْمَعُ بِهَا أَحَدٌ فَيَدْخُلُهَا. فَأَمَرَ بِهَا فَحُفَّتْ بِالشَّهَوَاتِ فَقَالَ ارْجِعْ إِلَيْهَا. فَرَجَعَ إِلَيْهَا فَقَالَ وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لاَ يَنْجُوَ مِنْهَا أَحَدٌ إِلاَّ دَخَلَهَا»"],"takhrij":"حسن: رواه أبو داود (٤٧٤٤)، والترمذي (٢٥٦٠)، والنسائي (٣٧٦٣)، وصححه ابن حبان (٧٣٩٤).","grade":"حسن","chapter_ar":"باب حفت الجنة بالمكاره وحفت النار بالشهوات","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4744), al-Tirmidhī (2560), al-Nasā’ī (3763), and authenticated by Ibn Ḥibbān (7394).","chapter_en":"Paradise Is Surrounded by Hardships and the Fire Is Surrounded by Desires","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When Allah created Paradise and the Fire, He sent Jibrīl to Paradise and said: ‘Look at it and at what I have prepared in it for its people.’ So he went to it and looked at it and at what Allah had prepared therein for its people. Then he returned and said: ‘By Your Might, no one will hear about it except that he will enter it.’ Then Allah commanded that it be surrounded by hardships and said: ‘Return to it and look at what I have prepared therein for its people.’","He returned and found that it had been surrounded by hardships. So he returned to Allah and said: ‘By Your Might, I fear that no one will enter it.’ Then He said: ‘Go to the Fire and look at it and at what I have prepared in it for its people.’ He went and saw its parts piled one upon another. He returned and said: ‘By Your Might, no one will hear about it and then enter it.’ Then Allah commanded that it be surrounded by desires and said: ‘Return to it.’","He returned and then said: ‘By Your Might, I fear that no one will escape it without entering it.’”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4744},{"key":"tirmidhi","label":"الترمذي","number":2560},{"key":"nasai","label":"النسائي","number":3763},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":7394}],"voc":["tirmidhi",2560]},{"num":16516,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، - رضى الله عنه - أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «إِذَا جَاءَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الْجَنَّةِ وَغُلِّقَتْ أَبْوَابُ النَّارِ وَصُفِّدَتِ الشَّيَاطِينُ»"],"takhrij":"متفق عليه: رواه البخاري (١٨٩٨)، ومسلم (١٠٧٩).","grade":"متفق عليه","chapter_ar":"باب تفتح أبواب الجنة وتغلق أبواب النار في شهر رمضان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1898) and Muslim (1079).","chapter_en":"The Gates of Paradise Are Opened and the Gates of the Fire Are Closed During the Month of Ramaḍān","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When Ramaḍān comes, the gates of Paradise are opened, the gates of the Fire are closed, and the devils are chained.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1898},{"key":"muslim","label":"مسلم","number":1079}],"voc":["muslim",2495]},{"num":16517,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ:","((إذا كان رمضان فتحت أبواب الرحمة، وغلقت أبواب جهنم، وسلسلت الشياطين))."],"takhrij":"متفق عليه: رواه البخاري (٣٢٧٧)، ومسلم (٢ :١٠٧٩).","grade":"متفق عليه","chapter_ar":"باب تفتح أبواب الجنة وتغلق أبواب النار في شهر رمضان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3277) and Muslim (2 :1079).","chapter_en":"The Gates of Paradise Are Opened and the Gates of the Fire Are Closed During the Month of Ramaḍān","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When Ramaḍān begins, the gates of mercy are opened, the gates of Hell are closed, and the devils are chained.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3277},{"key":"muslim","label":"مسلم","number":2}]},{"num":16518,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «لاَ يَدْخُلُ أَحَدٌ الْجَنَّةَ إِلاَّ أُرِيَ مَقْعَدَهُ مِنَ النَّارِ، لَوْ أَسَاءَ، لِيَزْدَادَ شُكْرًا، وَلاَ يَدْخُلُ النَّارَ أَحَدٌ إِلاَّ أُرِيَ مَقْعَدَهُ مِنَ الْجَنَّةِ، لَوْ أَحْسَنَ، لِيَكُونَ عَلَيْهِ حَسْرَةً»"],"takhrij":"صحيح: رواه البخاري (٦٥٦٩).","grade":"صحيح","chapter_ar":"باب أهل الجنة يرون مقاعدهم من النار لو أساؤوا، وأهل النار يرون مقاعدهم من الجنة لو أحسنوا","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6569).","chapter_en":"The People of Paradise Will See Their Places in the Fire Had They Done Evil, and the People of the Fire Will See Their Places in Paradise Had They Done Good","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “No one will enter Paradise except that he will be shown the place he would have occupied in the Fire had he done evil, so that he may increase in gratitude. And no one will enter the Fire except that he will be shown the place he would have occupied in Paradise had he done good, so that it may become a source of regret for him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6569}],"voc":["bukhari",6569]},{"num":16519,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ:","((كل أهل النار يرى منزله من الجنة، فيكون له حسرة فيقول: ﴿لَوْ أَنَّ اللَّهَ هَدَانِي لَكُنْتُ مِنَ الْمُتَّقِينَ﴾ [سورة الزمر: ٥٧]، وكل أهل الجنة يرى منزله من النار فيقول: ﴿وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ﴾ [سورة الأعراف: ٤٣]، فيكون له شكرًا)).","قال: وقال رسول اللّٰه ﷺ:","((ما من أحد إلا وله منزل في الجنة، ومنزل في النار، فالكافر يرث المؤمن منزله من النار، والمؤمن يرث الكافر منزله من الجنة، وذلك قوله تعالى: ﴿وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ﴾ [الزخرف: ٧٢]))."],"takhrij":"حسن: رواه ابن أبي حاتم في تفسيره - كما في تفسير ابن كثير - (٢٤٠/٧).","grade":"حسن","chapter_ar":"باب أهل الجنة يرون مقاعدهم من النار لو أساؤوا، وأهل النار يرون مقاعدهم من الجنة لو أحسنوا","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Ḥātim in his Tafsīr, as cited in Ibn Kathīr’s Tafsīr (7/240).","chapter_en":"The People of Paradise Will See Their Places in the Fire Had They Done Evil, and the People of the Fire Will See Their Places in Paradise Had They Done Good","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Every person from the people of the Fire will see the dwelling that would have been his in Paradise, and it will become a source of regret for him. He will say: ‘If only Allah had guided me, I would have been among the righteous.’ [al-Zumar 39:57] And every person from the people of Paradise will see the dwelling that would have been his in the Fire and will say: ‘We would never have been guided had Allah not guided us.’","[al-Aʿrāf 7:43] So this will increase him in gratitude.” He also said that the Messenger of Allah ﷺ said: “There is no one except that he has a dwelling in Paradise and a dwelling in the Fire. The disbeliever will inherit the believer’s dwelling in the Fire, and the believer will inherit the disbeliever’s dwelling in Paradise. That is the meaning of the statement of Allah, the Exalted: ‘That is the Paradise which you have been made to inherit because of what you used to do.’","[al-Zukhruf 43:72]”"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_حاتم/تفسیرہ_کما_فی_تفسیر_ابن_کثیر","label":"ابن أبي حاتم في تفسيره - كما في تفسير ابن كثير -","number":240}]},{"num":16520,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «يُؤْتَى بِأَنْعَمِ أَهْلِ الدُّنْيَا مِنْ أَهْلِ النَّارِ يَوْمَ الْقِيَامَةِ فَيُصْبَغُ فِي النَّارِ صَبْغَةً ثُمَّ يُقَالُ يَا ابْنَ آدَمَ هَلْ رَأَيْتَ خَيْرًا قَطُّ هَلْ مَرَّ بِكَ نَعِيمٌ قَطُّ فَيَقُولُ لاَ وَاللَّهِ يَا رَبِّ. وَيُؤْتَى بِأَشَدِّ النَّاسِ بُؤْسًا فِي الدُّنْيَا مِنْ أَهْلِ الْجَنَّةِ فَيُصْبَغُ صَبْغَةً فِي الْجَنَّةِ فَيُقَالُ لَهُ يَا ابْنَ آدَمَ هَلْ رَأَيْتَ بُؤْسًا قَطُّ هَلْ مَرَّ بِكَ شِدَّةٌ قَطُّ فَيَقُولُ لاَ وَاللَّهِ يَا رَبِّ مَا مَرَّ بِي بُؤُسٌ قَطُّ وَلاَ رَأَيْتُ شِدَّةً قَطُّ»"],"takhrij":"صحيح: رواه مسلم (٢٨٠٧).","grade":"صحيح","chapter_ar":"باب صبغ أنعم أهل الدنيا من أهل النار في النار، وصبغ أشد الناس بؤسًا من أهل الجنة في الجنة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2807).","chapter_en":"The Most Prosperous Person of This World among the People of the Fire Will Be Dipped into the Fire, and the Most Miserable Person of This World among the People of Paradise Will Be Dipped into Paradise","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “The person who enjoyed the greatest luxury in this world among those destined for the Fire will be brought on the Day of Resurrection and dipped once into the Fire. Then it will be said to him: ‘O son of Ādam, have you ever seen any good? Have you ever experienced any pleasure?’ He will say: ‘No, by Allah, my Lord.’ And the person who suffered the greatest misery in this world among those destined for Paradise will be brought and dipped once into Paradise.","Then it will be said to him: ‘O son of Ādam, have you ever experienced any misery? Have you ever gone through any hardship?’ He will say: ‘No, by Allah, my Lord. No misery ever passed over me, and I never experienced any hardship.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2807}],"voc":["muslim",7088]},{"num":16521,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ، وَالنَّارُ مِثْلُ ذَلِكَ»"],"takhrij":"صحيح: رواه البخاري (٦٤٨٨).","grade":"صحيح","chapter_ar":"باب قرب الجنة والنار من العبد","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6488).","chapter_en":"The Nearness of Paradise and the Fire to the Servant","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “Paradise is closer to each one of you than the strap of his sandal, and the Fire is likewise.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6488}],"voc":["bukhari",6488]},{"num":16522,"demo":false,"sanad":"","matn":["عَنِ الزُّهْرِيِّ،. وَحَدَّثَنِي مَحْمُودٌ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، أَخْبَرَنِي أَنَسُ بْنُ مَالِكٍ ـ رضى الله عنه. أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ حِينَ زَاغَتِ الشَّمْسُ فَصَلَّى الظُّهْرَ فَلَمَّا سَلَّمَ قَامَ عَلَى الْمِنْبَرِ فَذَكَرَ السَّاعَةَ، وَذَكَرَ أَنَّ بَيْنَ يَدَيْهَا أُمُورًا عِظَامًا ثُمَّ قَالَ «مَنْ أَحَبَّ أَنْ يَسْأَلَ عَنْ شَىْءٍ فَلْيَسْأَلْ عَنْهُ، فَوَاللَّهِ لاَ تَسْأَلُونِي عَنْ شَىْءٍ إِلاَّ أَخْبَرْتُكُمْ بِهِ، مَا دُمْتُ فِي مَقَامِي هَذَا»","قال أنس: فأكثر الناس البكاء، وأكثر رسول اللّٰه ﷺ أن يقول:","((سلوني)).","فقال أنس: فقام إليه رجل، فقال: أين مدخلي يا رسول الله؟ قال:","((النار)).","فقام عبد اللّٰه بن حذافة، فقال: من أبي يا رسول الله؟ قال:","((أبوك حذافة)).","قال: ثم أكثر أن يقول:","((سلوني، سلوني)).","فبرك عمر على ركبتيه، فقال: رضينا بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، قال: فسكت رسول اللّٰه ﷺ حين قال عمر ذلك، ثم قال رسول اللّٰه ﷺ:","((والذي نفسي بيده لقد عرضت علي الجنة والنار آنفًا في عرض هذا الحائط وأنا أصلي، فلم أر كاليوم في الخير والشر))."],"takhrij":"متفق عليه: رواه البخاري (٧٢٩٤) واللفظ له، ومسلم (١٣٦ :٢٣٩٥).","grade":"متفق عليه","chapter_ar":"باب عرض الجنة والنار على النبي ﷺ ورؤيته ما فيها من الخير والشر","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7294), whose wording this is, and Muslim (136 :2395).","chapter_en":"Paradise and the Fire Were Shown to the Prophet ﷺ, and He Saw the Good and Evil Contained in Them","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Prophet ﷺ came out after the sun had passed its zenith and prayed Ẓuhr. When he gave the salām, he stood upon the pulpit, mentioned the Hour, and mentioned that tremendous events would occur before it. Then he said: “Whoever wishes to ask about anything, let him ask. By Allah, you will not ask me about anything while I remain standing here except that I will inform you about it.” Anas said: The people began weeping intensely, while the Messenger of Allah ﷺ repeatedly said: “Ask me.”","A man stood and asked: “Where will I enter, O Messenger of Allah?” He replied: “The Fire.” Then ʿAbdullāh ibn Ḥudhāfah stood and asked: “Who is my father, O Messenger of Allah?” He replied: “Your father is Ḥudhāfah.” Then he continued saying: “Ask me, ask me.” ʿUmar fell to his knees and said: “We are pleased with Allah as our Lord, with Islam as our religion, and with Muḥammad as our Messenger.” When ʿUmar said that, the Messenger of Allah ﷺ became silent.","Then the Messenger of Allah ﷺ said: “By the One in whose hand is my soul, Paradise and the Fire were just now shown to me across this wall while I was praying. I have never seen anything like what I saw today in good and evil.”"]},"buhuth":{"ar":["ولم يعرف اسم الرجل الذي سأله أين مدخله فقال: ((النار)) إما أن يكون هذا الرجل منافقًا، أو فيه إشارة إلى سوء خاتمته، وإلا فالصحابة كلهم في الجنة لقوله تعالى:","﴿وَمَا لَكُمْ أَلَّا تُنْفِقُوا فِي سَبِيلِ اللَّهِ وَلِلَّهِ مِيرَاثُ السَّمَاوَاتِ وَالْأَرْضِ لَا يَسْتَوِي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَقَاتَلَ أُولَٰئِكَ أَعْظَمُ دَرَجَةً مِنَ الَّذِينَ أَنْفَقُوا مِنْ بَعْدُ وَقَاتَلُوا وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ﴾ [الحديد: ١٠].","وقال تعالى:","﴿إِنَّ الَّذِينَ سَبَقَتْ لَهُمْ مِنَّا الْحُسْنَىٰ أُولَٰئِكَ عَنْهَا مُبْعَدُونَ﴾ [الأنبياء: ١٠١]."],"en":["The identity of the man who asked where he would enter and was told “the Fire” is not known.","The author states that either this man was a hypocrite, or the statement indicated that his end would be evil. Otherwise, according to the author, the Companions are all destined for Paradise, based on the statement of Allah, the Exalted:","“Why should you not spend in the cause of Allah when to Allah belongs the inheritance of the heavens and the earth? Those among you who spent and fought before the Conquest are not equal to those who did so afterward. They are greater in rank than those who spent and fought afterward, though Allah has promised the best reward to all. And Allah is fully aware of what you do.”","[al-Ḥadīd 57:10]","And He, the Exalted, says:","“Indeed, those for whom the best reward has already gone forth from Us—they will be kept far away from it.”","[al-Anbiyāʾ 21:101]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7294},{"key":"muslim","label":"مسلم","number":136}],"voc":["bukhari",7294]},{"num":16523,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ «لاَ تَزَالُ جَهَنَّمُ يُلْقَى فِيهَا وَتَقُولُ هَلْ مِنْ مَزِيدٍ حَتَّى يَضَعَ رَبُّ الْعِزَّةِ فِيهَا قَدَمَهُ فَيَنْزَوِي بَعْضُهَا إِلَى بَعْضٍ وَتَقُولُ قَطْ قَطْ بِعِزَّتِكَ وَكَرَمِكَ. وَلاَ يَزَالُ فِي الْجَنَّةِ فَضْلٌ حَتَّى يُنْشِئَ اللَّهُ لَهَا خَلْقًا فَيُسْكِنَهُمْ فَضْلَ الْجَنَّةِ»"],"takhrij":"متفق عليه: رواه مسلم (٣٨ :٢٨٤٨) والبخاري (٧٣٨٤).","grade":"متفق عليه","chapter_ar":"باب ما جاء في سعة الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (38 :2848) and al-Bukhārī (7384).","chapter_en":"What Has Been Narrated Concerning the Vastness of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “People will continue to be cast into Hell while it says: ‘Is there any more?’ until the Lord of Might places His Foot in it. Then its parts will draw together and it will say: ‘Enough, enough, by Your Might and Your Generosity.’ And there will continue to remain extra space in Paradise until Allah creates a creation for it and settles them in the remaining space of Paradise.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":38},{"key":"bukhari","label":"البخاري","number":7384}],"voc":["muslim",7179]},{"num":16524,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أن رسول اللّٰه ﷺ قال: إِذَا صَارَ أَهْلُ الْجَنَّةِ إِلَى الْجَنَّةِ، وَأَهْلُ النَّارِ إِلَى النَّارِ، جِيءَ بِالْمَوْتِ حَتَّى يُجْعَلَ بَيْنَ الْجَنَّةِ وَالنَّارِ، ثُمَّ يُذْبَحُ، ثُمَّ يُنَادِي مُنَادٍ يَا أَهْلَ الْجَنَّةِ لاَ مَوْتَ، يَا أَهْلَ النَّارِ لاَ مَوْتَ، فَيَزْدَادُ أَهْلُ الْجَنَّةِ فَرَحًا إِلَى فَرَحِهِمْ. وَيَزْدَادُ أَهْلُ النَّارِ حُزْنًا إِلَى حُزْنِهِمْ"],"takhrij":"متفق عليه: رواه البخاري (٦٥٤٨)، ومسلم (٤٣ :٢٨٥٠).","grade":"متفق عليه","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6548) and Muslim (43 :2850).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “When the people of Paradise have gone to Paradise and the people of the Fire have gone to the Fire, death will be brought and placed between Paradise and the Fire, then it will be slaughtered. Then a caller will proclaim: ‘O people of Paradise, there is no more death! O people of the Fire, there is no more death!’ The people of Paradise will thereby increase in joy upon their joy, and the people of the Fire will increase in sorrow upon their sorrow.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا ۝ خَالِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا﴾ [الكهف: ١٠٧-١٠٨].","وقال تعالى:","﴿إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ أُولَٰئِكَ عَلَيْهِمْ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ۝ خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَ﴾ [البقرة: ١٦١-١٦٢]."],"en":["Allah, the Exalted, says:","“Indeed, those who believe and perform righteous deeds will have the Gardens of al-Firdaws as their hospitality, remaining therein forever, never desiring any change from it.”","[al-Kahf 18:107-108]","And He, the Exalted, says:","“Indeed, those who disbelieve and die while they are disbelievers—upon them is the curse of Allah, the angels, and all mankind, remaining therein forever. The punishment will not be lightened for them, nor will they be given respite.”","[al-Baqarah 2:161-162]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6548},{"key":"muslim","label":"مسلم","number":43}],"voc":["bukhari",6548]},{"num":16525,"demo":false,"sanad":"","matn":["عَنْ صَالِحٍ، حَدَّثَنَا نَافِعٌ، أَنَّ عَبْدَ اللَّهِ، قَالَ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «يُدْخِلُ اللَّهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ وَيُدْخِلُ أَهْلَ النَّارِ النَّارَ ثُمَّ يَقُومُ مُؤَذِّنٌ بَيْنَهُمْ فَيَقُولُ يَا أَهْلَ الْجَنَّةِ لاَ مَوْتَ وَيَا أَهْلَ النَّارِ لاَ مَوْتَ كُلٌّ خَالِدٌ فِيمَا هُوَ فِيهِ»"],"takhrij":"متفق عليه: رواه البخاري (٦٥٤٤)، ومسلم (٢٨٥٠).","grade":"متفق عليه","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6544) and Muslim (2850).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Allah will admit the people of Paradise into Paradise and the people of the Fire into the Fire. Then a caller will stand between them and proclaim: ‘O people of Paradise, there is no death! O people of the Fire, there is no death! Everyone will remain forever in the state in which he is.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6544},{"key":"muslim","label":"مسلم","number":2850}],"voc":["muslim",7183]},{"num":16526,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «يُؤْتَى بِالْمَوْتِ كَهَيْئَةِ كَبْشٍ أَمْلَحَ فَيُنَادِي مُنَادٍ يَا أَهْلَ الْجَنَّةِ، فَيَشْرَئِبُّونَ وَيَنْظُرُونَ فَيَقُولُ هَلْ تَعْرِفُونَ هَذَا فَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ، وَكُلُّهُمْ قَدْ رَآهُ، ثُمَّ يُنَادِي يَا أَهْلَ النَّارِ، فَيَشْرَئِبُّونَ وَيَنْظُرُونَ، فَيَقُولُ هَلْ تَعْرِفُونَ هَذَا فَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ، وَكُلُّهُمْ قَدْ رَآهُ، فَيُذْبَحُ ثُمَّ يَقُولُ يَا أَهْلَ الْجَنَّةِ، خُلُودٌ فَلاَ مَوْتَ، وَيَا أَهْلَ النَّارِ، خُلُودٌ فَلاَ مَوْتَ ثُمَّ قَرَأَ {وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الأَمْرُ وَهُمْ فِي غَفْلَةٍ} وَهَؤُلاَءِ فِي غَفْلَةٍ أَهْلُ الدُّنْيَا {وَهُمْ لاَ يُؤْمِنُونَ}»"],"takhrij":"متفق عليه: رواه البخاري (٤٧٣٠)، ومسلم (٢٨٤٩).","grade":"متفق عليه","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4730) and Muslim (2849).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Death will be brought in the form of a black-and-white ram. A caller will proclaim: ‘O people of Paradise!’ They will crane their necks and look. He will ask: ‘Do you recognize this?’ They will reply: ‘Yes. This is death,’ for all of them will have seen it. Then he will call: ‘O people of the Fire!’ They will crane their necks and look. He will ask: ‘Do you recognize this?’","They will reply: ‘Yes. This is death,’ for all of them will have seen it. Then it will be slaughtered, and it will be said: ‘O people of Paradise, everlasting life with no death! O people of the Fire, everlasting life with no death!’” Then he recited: “Warn them of the Day of Regret, when the matter will have been decided while they are in heedlessness.” [Maryam 19:39] These people are presently in the heedlessness of this worldly life: “And they do not believe.”","[Maryam 19:39]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4730},{"key":"muslim","label":"مسلم","number":2849}],"voc":["bukhari",4730]},{"num":16527,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «يُقَالُ لأَهْلِ الْجَنَّةِ خُلُودٌ لاَ مَوْتَ. وَلأَهْلِ النَّارِ يَا أَهْلَ النَّارِ خُلُودٌ لاَ مَوْتَ»"],"takhrij":"صحيح: رواه البخاري (٦٥٤٥).","grade":"صحيح","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6545).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “It will be said to the people of Paradise: ‘Everlasting life with no death,’ and to the people of the Fire: ‘O people of the Fire, everlasting life with no death.’”"]},"buhuth":{"ar":["ورواه الإمام أحمد (٨٥٣٥) من وجه آخر مرفوعًا ولفظه:","((إذا دخل أهل الجنة الجنة، وأهل النار النار نادى مناد: يا أهل الجنة خلود فلا موت فيه، ويا أهل النار خلود فلا موت فيه))."],"en":["Imām Aḥmad (8535) also narrated it through another route as a Prophetic report with the wording:","“When the people of Paradise have entered Paradise and the people of the Fire have entered the Fire, a caller will proclaim: ‘O people of Paradise, everlasting life with no death therein! O people of the Fire, everlasting life with no death therein!’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6545}],"voc":["bukhari",6545]},{"num":16528,"demo":false,"sanad":"","matn":["فَإِذَا أَدْخَلَ اللَّهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ وَأَهْلَ النَّارِ النَّارَ قَالَ أُتِيَ بِالْمَوْتِ مُلَبَّبًا فَيُوقَفُ عَلَى السُّورِ الَّذِي بَيْنَ أَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ ثُمَّ يُقَالُ يَا أَهْلَ الْجَنَّةِ. فَيَطَّلِعُونَ خَائِفِينَ ثُمَّ يُقَالُ يَا أَهْلَ النَّارِ. فَيَطَّلِعُونَ مُسْتَبْشِرِينَ يَرْجُونَ الشَّفَاعَةَ فَيُقَالُ لأَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ هَلْ تَعْرِفُونَ هَذَا فَيَقُولُونَ هَؤُلاَءِ وَهَؤُلاَءِ قَدْ عَرَفْنَاهُ هُوَ الْمَوْتُ الَّذِي وُكِّلَ بِنَا. فَيُضْجَعُ فَيُذْبَحُ ذَبْحًا عَلَى السُّورِ الَّذِي بَيْنَ الْجَنَّةِ وَالنَّارِ ثُمَّ يُقَالُ يَا أَهْلَ الْجَنَّةِ خُلُودٌ لاَ مَوْتَ وَيَا أَهْلَ النَّارِ خُلُودٌ لاَ مَوْتَ"],"takhrij":"حسن: رواه الترمذي (٢٥٥٧)، وابن خزيمة في التوحيد (١٥٠).","grade":"حسن","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2557) and Ibn Khuzaymah in al-Tawḥīd (150).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said in a lengthy hadith: “When Allah has admitted the people of Paradise into Paradise and the people of the Fire into the Fire, death will be brought restrained and made to stand upon the wall between the people of Paradise and the people of the Fire. Then it will be said: ‘O people of Paradise!’ and they will look out fearfully. Then it will be said: ‘O people of the Fire!’ and they will look out joyfully, hoping for intercession.","Then both the people of Paradise and the people of the Fire will be asked: ‘Do you recognize this?’ Both groups will say: ‘We recognize it. It is death, which had been appointed over us.’ Then it will be laid down and slaughtered upon the wall between Paradise and the Fire. Then it will be said: ‘O people of Paradise, everlasting life with no death! O people of the Fire, everlasting life with no death!’”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2557},{"key":"ابن_خزیمہ/التوحید","label":"ابن خزيمة في التوحيد","number":150}],"voc":["tirmidhi",2557]},{"num":16529,"demo":false,"sanad":"","matn":["عَنْ أنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «يُؤْتَى بِالْمَوْتِ يَوْمَ الْقِيَامَةِ، فَيُوقَفُ بَيْنَ الْجَنَّةِ وَالنَّارِ، فَيُذْبَحُ، فَيُقَالُ: يَا أَهْلَ الْجَنَّةِ خُلُودٌ لا مَوْتَ، وَيَا أَهْلَ النَّارِ خُلُودٌ لا مَوْتَ»"],"takhrij":"حسن: رواه البزار (٧٢٤٠)، وأبو يعلى (٢٨٩٨)، والطبراني في الأوسط (٣٦٧٢)، والضياء في المختارة (٢٤٤٧).","grade":"حسن","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (7240), Abū Yaʿlā (2898), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (3672), and al-Ḍiyāʾ in al-Aḥādīth al-Mukhtārah (2447).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “Death will be brought on the Day of Resurrection and made to stand between Paradise and the Fire, then it will be slaughtered. It will be said: ‘O people of Paradise, everlasting life with no death! O people of the Fire, everlasting life with no death!’”"]}},"tuhfa":{},"refs":[{"key":"البزار","label":"البزار","number":7240},{"key":"ابو_یعلی","label":"أبو يعلى","number":2898},{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":3672},{"key":"الضیا/المختارہ","label":"الضياء في المختارة","number":2447},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":3557,"n":3558}],"voc":["sh12862",3558]},{"num":16530,"demo":false,"sanad":"","matn":["عن سعيد بن وهب الهمداني قال: قدم علينا معاذ بن جبل فقال: إني رسول رسول اللّٰه ﷺ إليكم:","((أن تعبدوا الله ولا تشركوا به شيئًا، وأن تطيعوني لا آلوكم خيرًا، وأن المصير إلى اللّٰه تعالى، وإلى الجنة والنار، إقامة بلا ظعن، وخلود بلا موت))."],"takhrij":"صحيح: رواه إسحاق بن راهويه في مسنده كما في إتحاف الخيرة المهرة (٥٨)، والمطالب العالية (٢٨٦٢).","grade":"صحيح","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Isḥāq ibn Rāhawayh in his Musnad, as cited in Itḥāf al-Khiyarah al-Maharah (58) and al-Maṭālib al-ʿĀliyah (2862).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":66,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Saʿīd ibn Wahb al-Hamdānī narrated: Muʿādh ibn Jabal came to us and said: “I am the messenger of the Messenger of Allah ﷺ to you, conveying: ‘That you worship Allah and associate nothing with Him; that you obey me, for I will spare no effort in directing you toward good; and that the final return is to Allah, the Exalted, and to Paradise or the Fire—an abiding without departure and an eternity without death.’”"]}},"tuhfa":{},"refs":[{"key":"اسحاق_بن_راہویہ/مسندہ_کما_فی_اتحاف_الخیرہ_المہرہ","label":"إسحاق بن راهويه في مسنده كما في إتحاف الخيرة المهرة","number":58},{"key":"المطالب_العالیہ","label":"المطالب العالية","number":2862}]},{"num":16531,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَا الْمُوجِبَتَانِ فَقَالَ «مَنْ مَاتَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ»"],"takhrij":"صحيح: رواه مسلم (٩٣).","grade":"صحيح","chapter_ar":"باب من مات لا يشرك بالله شيئًا دخل الجنة، ومن مات يشرك بالله شيئًا دخل النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (93).","chapter_en":"Whoever Dies Without Associating Anything with Allah Will Enter Paradise, and Whoever Dies Associating Anything with Allah Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: A man came to the Prophet ﷺ and asked: “O Messenger of Allah, what are the two things that make the outcome certain?” He replied: “Whoever dies without associating anything with Allah will enter Paradise, and whoever dies associating anything with Allah will enter the Fire.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":93}],"voc":["muslim",269]},{"num":16532,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «قُمْتُ عَلَى باب الْجَنَّةِ فَكَانَ عَامَّةَ مَنْ دَخَلَهَا الْمَسَاكِينُ، وَأَصْحَابُ الْجَدِّ مَحْبُوسُونَ، غَيْرَ أَنَّ أَصْحَابَ النَّارِ قَدْ أُمِرَ بِهِمْ إِلَى النَّارِ، وَقُمْتُ عَلَى باب النَّارِ فَإِذَا عَامَّةُ مَنْ دَخَلَهَا النِّسَاءُ»"],"takhrij":"متفق عليه: رواه البخاري (٥١٩٦)، ومسلم (٢٧٣٦).","grade":"متفق عليه","chapter_ar":"باب أكثر أهل الجنة الفقراء، وأكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5196) and Muslim (2736).","chapter_en":"Most of the People of Paradise Are the Poor, and Most of the People of the Fire Are Women","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Usāmah ibn Zayd narrated that the Prophet ﷺ said: “I stood at the gate of Paradise and saw that most of those who entered it were the poor, while the people of wealth and worldly fortune were being detained, except that those destined for the Fire had already been ordered to the Fire. And I stood at the gate of the Fire and saw that most of those who entered it were women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5196},{"key":"muslim","label":"مسلم","number":2736}],"voc":["bukhari",5196]},{"num":16533,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «اطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ وَاطَّلَعْتُ فِي النَّارِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ»"],"takhrij":"صحيح: رواه البخاري (٦٥٤٦).","grade":"صحيح","chapter_ar":"باب أكثر أهل الجنة الفقراء، وأكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6546).","chapter_en":"Most of the People of Paradise Are the Poor, and Most of the People of the Fire Are Women","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["ʿImrān narrated that the Prophet ﷺ said: “I looked into Paradise and saw that most of its inhabitants were the poor, and I looked into the Fire and saw that most of its inhabitants were women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6546}],"voc":["bukhari",6546]},{"num":16534,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال محمد ﷺ:","((اطلعت في الجنة فرأيت أكثر أهلها الفقراء، واطلعت في النار فرأيت أكثر أهلها النساء))."],"takhrij":"صحيح: رواه مسلم (٢٧٣٧).","grade":"صحيح","chapter_ar":"باب أكثر أهل الجنة الفقراء، وأكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2737).","chapter_en":"Most of the People of Paradise Are the Poor, and Most of the People of the Fire Are Women","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās narrated that Muḥammad ﷺ said: “I looked into Paradise and saw that most of its inhabitants were the poor, and I looked into the Fire and saw that most of its inhabitants were women.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2737}]},{"num":16535,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رضى الله عنه قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «تَحَاجَّتِ الْجَنَّةُ وَالنَّارُ فَقَالَتِ النَّارُ أُوثِرْتُ بِالْمُتَكَبِّرِينَ وَالْمُتَجَبِّرِينَ. وَقَالَتِ الْجَنَّةُ مَا لِي لاَ يَدْخُلُنِي إِلاَّ ضُعَفَاءُ النَّاسِ وَسَقَطُهُمْ. قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى لِلْجَنَّةِ أَنْتِ رَحْمَتِي أَرْحَمُ بِكِ مَنْ أَشَاءُ مِنْ عِبَادِي. وَقَالَ لِلنَّارِ إِنَّمَا أَنْتِ عَذَابٌ أُعَذِّبُ بِكِ مَنْ أَشَاءُ مِنْ عِبَادِي. وَلِكُلِّ وَاحِدَةٍ مِنْهُمَا مِلْؤُهَا، فَأَمَّا النَّارُ فَلاَ تَمْتَلِئُ حَتَّى يَضَعَ رِجْلَهُ فَتَقُولُ قَطٍ قَطٍ قَطٍ. فَهُنَالِكَ تَمْتَلِئُ وَيُزْوَى بَعْضُهَا إِلَى بَعْضٍ، وَلاَ يَظْلِمُ اللَّهُ ـ عَزَّ وَجَلَّ ـ مِنْ خَلْقِهِ أَحَدًا، وَأَمَّا الْجَنَّةُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُنْشِئُ لَهَا خَلْقًا»"],"takhrij":"متفق عليه: رواه البخاري (٤٨٥٠)، ومسلم (٣٦/٢٨٤٦).","grade":"متفق عليه","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4850) and Muslim (36/2846).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Paradise and the Fire disputed with one another. The Fire said: ‘I have been favored with the arrogant and the tyrannical.’ Paradise said: ‘Why is it that none enter me except the weak, insignificant, and simple-minded among the people?’ Allah said to Paradise: ‘You are My mercy; through you I show mercy to whomever I will among My servants.’ And He said to the Fire: ‘You are My punishment; through you I punish whomever I will among My servants. Each of you will have its fill.’","As for the Fire, it will not become full until Allah, Blessed and Exalted, places His Foot in it, and it will say: ‘Enough, enough, enough.’ Then it will become full and its parts will contract together. Allah will not wrong anyone among His creation. As for Paradise, Allah will create a creation for it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4850},{"key":"muslim","label":"مسلم","number":36}],"voc":["bukhari",4850]},{"num":16536,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «اخْتَصَمَتِ الْجَنَّةُ وَالنَّارُ إِلَى رَبِّهِمَا فَقَالَتِ الْجَنَّةُ يَا رَبِّ مَا لَهَا لاَ يَدْخُلُهَا إِلاَّ ضُعَفَاءُ النَّاسِ وَسَقَطُهُمْ. وَقَالَتِ النَّارُ ـ يَعْنِي ـ أُوثِرْتُ بِالْمُتَكَبِّرِينَ. فَقَالَ اللَّهُ تَعَالَى لِلْجَنَّةِ أَنْتِ رَحْمَتِي. وَقَالَ لِلنَّارِ أَنْتِ عَذَابِي أُصِيبُ بِكِ مَنْ أَشَاءُ، وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا ـ قَالَ ـ فَأَمَّا الْجَنَّةُ فَإِنَّ اللَّهَ لاَ يَظْلِمُ مِنْ خَلْقِهِ أَحَدًا، وَإِنَّهُ يُنْشِئُ لِلنَّارِ مَنْ يَشَاءُ فَيُلْقَوْنَ فِيهَا فَتَقُولُ هَلْ مِنْ مَزِيدٍ. ثَلاَثًا، حَتَّى يَضَعَ فِيهَا قَدَمَهُ فَتَمْتَلِئُ وَيُرَدُّ بَعْضُهَا إِلَى بَعْضٍ وَتَقُولُ قَطْ قَطْ قَطْ»"],"takhrij":"متفق عليه: رواه البخاري (٧٤٤٩) ومسلم (٢٨٤٦).","grade":"متفق عليه","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7449) and Muslim (2846).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Paradise and the Fire brought their dispute before their Lord. Paradise said: ‘My Lord, why is it that none enter me except the weak and insignificant among the people?’ The Fire said—meaning—‘I have been favored with the arrogant.’ Allah, the Exalted, said to Paradise: ‘You are My mercy.’ And He said to the Fire: ‘You are My punishment; through you I afflict whomever I will. Each of you will have its fill.’","As for Paradise, Allah does not wrong anyone among His creation. And He creates for the Fire whomever He wills, and they are cast into it. It says three times: ‘Is there any more?’ until He places His Foot in it. Then it becomes full, its parts are drawn together, and it says: ‘Enough, enough, enough.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7449},{"key":"muslim","label":"مسلم","number":2846}],"voc":["bukhari",7449]},{"num":16537,"demo":false,"sanad":"","matn":["عَنْ حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ «أَلاَ أُخْبِرُكُمْ بِأَهْلِ الْجَنَّةِ، كُلُّ ضَعِيفٍ مُتَضَاعِفٍ، لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ، أَلاَ أُخْبِرُكُمْ بِأَهْلِ النَّارِ كُلُّ عُتُلٍّ جَوَّاظٍ مُسْتَكْبِرٍ»"],"takhrij":"متفق عليه: رواه البخاري (٦٠٧١)، ومسلم (٢٨٥٣).","grade":"متفق عليه","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6071) and Muslim (2853).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Ḥārithah ibn Wahb al-Khuzāʿī narrated that the Prophet ﷺ said: “Shall I tell you about the people of Paradise? Every weak person who is regarded as weak; if he were to swear an oath by Allah, Allah would fulfill it for him. And shall I tell you about the people of the Fire? Every harsh, coarse, arrogant person.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6071},{"key":"muslim","label":"مسلم","number":2853}],"voc":["bukhari",6071]},{"num":16538,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «احْتَجَّتِ الْجَنَّةُ وَالنَّارُ، فَقَالَتِ النَّارُ: فِيَّ الْجَبَّارُونَ وَالْمُتَكَبِّرُونَ، وَقَالَتِ الْجَنَّةُ: فِيَّ ضُعَفَاءُ النَّاسِ وَمَسَاكِينُهُمْ، قَالَ: فَقَضَى بَيْنَهُمَا، إِنَّكِ الْجَنَّةُ رَحْمَتِي أَرْحَمُ بِكِ مَنْ أَشَاءُ، وَإِنَّكِ النَّارُ عَذَابِي أُعَذِّبُ بِكِ مَنْ أَشَاءُ، وَلِكِلَاكُمَا عَلَيَّ مِلْؤُهَا»"],"takhrij":"صحيح: رواه مسلم (٢٨٤٧)، والإمام أحمد (١١٧٥٤) واللفظ لأحمد، ومسلم لم يسق لفظه.","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2847) and Imām Aḥmad (11754). The wording is Aḥmad’s; Muslim did not quote the full wording.","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Paradise and the Fire disputed. The Fire said: ‘Within me are the tyrants and the arrogant.’ Paradise said: ‘Within me are the weak and poor among the people.’ Allah then judged between them: ‘You, Paradise, are My mercy; through you I show mercy to whomever I will. And you, Fire, are My punishment; through you I punish whomever I will. It is upon Me to fill each of you.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2847},{"key":"الامام_احمد","label":"الإمام أحمد","number":11754},{"key":"ahmad","label":"مسند الإمام أحمد","number":11754,"n":11754}],"voc":["ahmad",11754]},{"num":16539,"demo":false,"sanad":"","matn":["عَنْ عِيَاضِ بْنِ حِمَارٍ الْمُجَاشِعِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ذَاتَ يَوْمٍ فِي خُطْبَتِهِ «أَلاَ إِنَّ رَبِّي أَمَرَنِي أَنْ أُعَلِّمَكُمْ مَا جَهِلْتُمْ مِمَّا عَلَّمَنِي يَوْمِي هَذَا كُلُّ مَالٍ نَحَلْتُهُ عَبْدًا حَلاَلٌ وَإِنِّي خَلَقْتُ عِبَادِي حُنَفَاءَ كُلَّهُمْ وَإِنَّهُمْ أَتَتْهُمُ الشَّيَاطِينُ فَاجْتَالَتْهُمْ عَنْ دِينِهِمْ وَحَرَّمَتْ عَلَيْهِمْ مَا أَحْلَلْتُ لَهُمْ وَأَمَرَتْهُمْ أَنْ يُشْرِكُوا بِي مَا لَمْ أُنْزِلْ بِهِ سُلْطَانًا وَإِنَّ اللَّهَ نَظَرَ إِلَى أَهْلِ الأَرْضِ فَمَقَتَهُمْ عَرَبَهُمْ وَعَجَمَهُمْ إِلاَّ بَقَايَا مِنْ أَهْلِ الْكِتَابِ وَقَالَ إِنَّمَا بَعَثْتُكَ لأَبْتَلِيَكَ وَأَبْتَلِيَ بِكَ وَأَنْزَلْتُ عَلَيْكَ كِتَابًا لاَ يَغْسِلُهُ الْمَاءُ تَقْرَؤُهُ نَائِمًا وَيَقْظَانَ وَإِنَّ اللَّهَ أَمَرَنِي أَنْ أُحَرِّقَ قُرَيْشًا فَقُلْتُ رَبِّ إِذًا يَثْلَغُوا رَأْسِي فَيَدَعُوهُ خُبْزَةً قَالَ اسْتَخْرِجْهُمْ كَمَا اسْتَخْرَجُوكَ وَاغْزُهُمْ نُغْزِكَ وَأَنْفِقْ فَسَنُنْفِقَ عَلَيْكَ وَابْعَثْ جَيْشًا نَبْعَثْ خَمْسَةً مِثْلَهُ وَقَاتِلْ بِمَنْ أَطَاعَكَ مَنْ عَصَاكَ. قَالَ وَأَهْلُ الْجَنَّةِ ثَلاَثَةٌ ذُو سُلْطَانٍ مُقْسِطٌ مُتَصَدِّقٌ مُوَفَّقٌ وَرَجُلٌ رَحِيمٌ رَقِيقُ الْقَلْبِ لِكُلِّ ذِي قُرْبَى وَمُسْلِمٍ وَعَفِيفٌ مُتَعَفِّفٌ ذُو عِيَالٍ - قَالَ - وَأَهْلُ النَّارِ خَمْسَةٌ الضَّعِيفُ الَّذِي لاَ زَبْرَ لَهُ الَّذِينَ هُمْ فِيكُمْ تَبَعًا لاَ يَتْبَعُونَ أَهْلاً وَلاَ مَالاً وَالْخَائِنُ الَّذِي لاَ يَخْفَى لَهُ طَمَعٌ وَإِنْ دَقَّ إِلاَّ خَانَهُ وَرَجُلٌ لاَ يُصْبِحُ وَلاَ يُمْسِي إِلاَّ وَهُوَ يُخَادِعُكَ عَنْ أَهْلِكَ وَمَالِكَ». وَذَكَرَ الْبُخْلَ أَوِ الْكَذِبَ «وَالشِّنْظِيرُ الْفَحَّاشُ». وَلَمْ يَذْكُرْ أَبُو غَسَّانَ فِي حَدِيثِهِ «وَأَنْفِقْ فَسَنُنْفِقَ عَلَيْكَ»"],"takhrij":"صحيح: رواه مسلم (٢٨٦٥).","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2865).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["ʿIyāḍ ibn Ḥimār al-Mujāshiʿī narrated that the Messenger of Allah ﷺ said one day in his sermon: “Indeed, my Lord has commanded me to teach you today what you did not know from what He has taught me. Every wealth that I have granted to a servant is lawful. I created all My servants inclining naturally toward the truth, but the devils came to them and turned them away from their religion. They prohibited for them what I had made lawful and commanded them to associate with Me that for which I had sent down no authority.","Allah looked upon the people of the earth and detested them, Arabs and non-Arabs alike, except for remnants among the People of the Book. And He said: ‘I have only sent you in order to test you and test others through you. I have revealed to you a Book that water cannot wash away; you recite it while asleep and awake.’ Allah commanded me to burn Quraysh. I said: ‘My Lord, then they will crush my head and leave it like a loaf of bread.’ He said: ‘Drive them out as they drove you out. Fight them and We will support you. Spend and We will spend upon you. Send an army and We will send five times its number. Fight with those who obey you against those who disobey you.’","The people of Paradise are three: a ruler who is just, charitable, and guided to success; a merciful man whose heart is tender toward every relative and Muslim; and a chaste person who restrains himself despite having dependents. And the people of the Fire are five: the weak person who has no resolve, those who merely follow among you and seek neither family nor wealth; the treacherous person whose greed, however slight, never escapes him without his betraying it; and a man who morning and evening never ceases trying to deceive you regarding your family and wealth.”","He also mentioned: “Miserliness—or lying—and the foul-mouthed, obscene person.” Abū Ghassān did not mention in his narration: “Spend and We will spend upon you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2865}],"voc":["muslim",7207]},{"num":16540,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّ أَهْلَ النَّارِ كُلُّ جَعْظَرِيٍّ جَوَّاظٍ مُسْتَكْبِرٍ، جَمَّاعٍ مَنَّاعٍ، وَأَهْلُ الْجَنَّةِ الضُّعَفَاءُ الْمَغْلُوبُونَ»"],"takhrij":"صحيح: رواه أحمد (٧٠١٠)، والحاكم (٤٩٩/٢).","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (7010) and al-Ḥākim (2/499).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “The people of the Fire are every harsh, coarse, arrogant person, one who amasses wealth and withholds it. And the people of Paradise are the weak and oppressed.”"]},"buhuth":{"ar":["قوله: “جعظري” هو الفظ الغليظ. وقوله: “جواظ” هو المختال في مشيته."],"en":["The author explains that “jaʿẓarī” means a harsh and coarse person.","“Jawwāẓ” means one who walks with arrogance and conceit."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":499},{"key":"ahmad","label":"مسند الإمام أحمد","number":7010,"n":7010}],"voc":["ahmad",7010]},{"num":16541,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللهِ بْنِ شَقِيقٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «أَلَا أَدُلُّكُمْ عَلَى أَهْلِ الْجَنَّةِ؟»","قالوا: بلى، قال:","((الضعفاء المتظلمون)).","ثم قال:","((ألا أدلكم على أهل النار؟)).","قالوا: بلى، قال:","((كل شديد جعظري))."],"takhrij":"صحيح: رواه أحمد (٢٣١٣١).","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23131).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Shaqīq narrated from a man among the Companions of the Prophet ﷺ that the Prophet ﷺ said: “Shall I direct you to the people of Paradise?” They replied: “Yes.” He said: “The weak who are oppressed.” Then he said: “Shall I direct you to the people of the Fire?” They replied: “Yes.” He said: “Every harsh, coarse person.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23131,"n":23131}],"voc":["ahmad",23131]},{"num":16542,"demo":false,"sanad":"","matn":["عَنْ سُرَاقَةَ بْنِ مَالِكِ بْنِ جُعْشُمٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ لَهُ: «يَا سُرَاقَةُ أَلَا أُخْبِرُكَ بِأَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ» فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، فَقَالَ: «أَمَّا أَهْلُ النَّارِ فَكُلُّ جَعْظَرِيٍّ جَوَّاظٌ مُسْتَكْبِرٌ، وَأَمَّا أَهْلُ الْجَنَّةِ فَالضُّعَفَاءُ الْمَغْلُوبُونَ»"],"takhrij":"حسن: رواه الطبراني في الكبير (١٥٢/٧)، والحاكم (٦١٩/٣).","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (7/152) and al-Ḥākim (3/619).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Surāqah ibn Mālik ibn Juʿshum al-Mudlijī narrated that the Messenger of Allah ﷺ said: “O Surāqah, shall I tell you about the people of Paradise and the people of the Fire?” He replied: “Yes, O Messenger of Allah.” He said: “As for the people of the Fire, they are every harsh, coarse, arrogant person. As for the people of Paradise, they are the weak and oppressed.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":152},{"key":"hakim","label":"المستدرك على الصحيحين","number":6597,"n":6595}],"voc":["hakim",6595]},{"num":16543,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَلَا أُنَبِّئُكُمْ بِأَهْلِ الْجَنَّةِ؟ هُمُ الضُّعَفَاءُ الْمَظْلُومُونَ، أَلَا أُنَبِّئُكُمْ بِأَهْلِ النَّارِ؟ كُلُّ شَدِيدٍ جَعْظَرِيٍّ»"],"takhrij":"حسن: رواه أحمد (٨٨٢١)، وأبو يعلى (٦١٢٧)، والطبراني في الأوسط (٤٢٧٥)، والبيهقي في شعب الإيمان (٧٨٢٦).","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8821), Abū Yaʿlā (6127), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (4275), and al-Bayhaqī in Shuʿab al-Īmān (7826).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Shall I inform you about the people of Paradise? They are the weak and oppressed. Shall I inform you about the people of the Fire? Every harsh, coarse person.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":6127},{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":4275},{"key":"البیہقی/شعب_الایمان","label":"البيهقي في شعب الإيمان","number":7826},{"key":"ahmad","label":"مسند الإمام أحمد","number":8821,"n":8821}],"voc":["ahmad",8821]},{"num":16544,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: «أَلَا أُخْبِرُكُمْ بِأَهْلِ النَّارِ وَأَهْلِ الْجَنَّةِ؟ أَمَّا أَهْلُ الْجَنَّةِ، فَكُلُّ ضَعِيفٍ مُتَضَعِّفٍ، أَشْعَثَ ذِي طِمْرَيْنِ، لَوْ أَقْسَمَ عَلَى اللهِ لَأَبَرَّهُ، وَأَمَّا أَهْلُ النَّارِ، فَكُلُّ جَعْظَرِيٍّ جَوَّاظٍ، جَمَّاعٍ مَنَّاعٍ، ذِي تَبَعٍ»"],"takhrij":"حسن: رواه أحمد (١٢٤٧٦) وأبو يعلى (٣٩٨٧).","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12476) and Abū Yaʿlā (3987).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Shall I tell you about the people of the Fire and the people of Paradise? As for the people of Paradise, they are every weak person regarded as weak, disheveled and wearing two worn garments; if he were to swear an oath by Allah, Allah would fulfill it for him. As for the people of the Fire, they are every harsh, coarse person who amasses and withholds wealth and has followers.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":3987},{"key":"ahmad","label":"مسند الإمام أحمد","number":12476,"n":12476}],"voc":["ahmad",12476]},{"num":16545,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «أَلاَ أُخْبِرُكُمْ بِمَنْ يَحْرُمُ عَلَى النَّارِ أَوْ بِمَنْ تَحْرُمُ عَلَيْهِ النَّارُ عَلَى كُلِّ قَرِيبٍ هَيِّنٍ لَيِّنٍ سَهْلٍ»"],"takhrij":"حسن: رواه الترمذي (٢٤٨٨)، وأحمد (٣٩٣٨)، وأبو يعلى (٥٠٥٣)، وابن حبان (٤٧٠، ٤٦٩).","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2488), Aḥmad (3938), Abū Yaʿlā (5053), and Ibn Ḥibbān (470, 469).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Shall I tell you about the one who will be forbidden to the Fire—or the one upon whom the Fire will be forbidden? It is every person who is approachable, gentle, and easy-going.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2488},{"key":"ابو_یعلی","label":"أبو يعلى","number":5053},{"key":"ibnhibban","label":"ابن حبان","number":470},{"key":"ahmad","label":"مسند الإمام أحمد","number":3938,"n":3938},{"key":"sh12520","label":"مسند أبي يعلى","number":5053,"n":5058}],"voc":["tirmidhi",2488]},{"num":16546,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ «كَلِمَتَانِ حَبِيبَتَانِ إِلَى الرَّحْمَنِ، خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ»"],"takhrij":"متفق عليه: رواه البخاري (٧٥٦٣)، ومسلم (٢٦٩٤).","grade":"متفق عليه","chapter_ar":"باب في صفة العدل لله تعالى يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7563) and Muslim (2694).","chapter_en":"Concerning the Justice of Allah, the Exalted, on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":66,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Two phrases are beloved to the Most Merciful, light upon the tongue, and heavy upon the Scale: Subḥān Allāhi wa biḥamdih — Glory and praise be to Allah. Subḥān Allāhil-ʿAẓīm — Glory be to Allah, the Magnificent.”"]},"intro":{"ar":["قال تعالى:","﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِنْ كَانَ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَاسِبِينَ﴾ [الأنبياء: ٤٧].","يخبر اللّه تعالى عن عدله، وقضائه القسط بين عباده إذا جمعهم يوم القيامة."],"en":["Allah, the Exalted, says:","“We will set up the scales of justice for the Day of Resurrection, so no soul will be wronged in the least. Even if a deed is the weight of a mustard seed, We will bring it forth. And sufficient are We as Reckoners.”","[al-Anbiyāʾ 21:47]","Allah, the Exalted, informs us of His perfect justice and His judging with equity between His servants when He gathers them on the Day of Resurrection."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7563},{"key":"muslim","label":"مسلم","number":2694}],"voc":["bukhari",7563]}]);
